#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Enrichissement de cinema.json — 20 articles à porter à 15000+ chars."""
import json

ENRICHMENTS = {
    "animation/animation-3d": """<h3>Les pionniers de l'animation 3D : Pixar et la révolution numérique</h3><p class="resume-text">Pixar Animation Studios, fondé par Ed Catmull, John Lasseter et Steve Jobs en 1986, a révolutionné l'animation mondiale avec Toy Story (1995), premier long métrage entièrement réalisé en images de synthèse 3D. Ce film a transformé non seulement la technique mais aussi les attentes du public et les modèles économiques de l'animation. La technologie RenderMan, développée par Pixar, est devenue le standard industriel du rendu 3D et a remporté un Oscar technique pour son impact sur l'industrie cinématographique.</p><p class="resume-text">La chaîne de production 3D est radicalement différente de l'animation traditionnelle. Les artistes travaillent sur des logiciels complexes (Maya, Houdini, RenderMan) pour modéliser les personnages, créer leurs squelettes d'animation (rigging), simuler les tissus et les cheveux, générer l'éclairage et calculer le rendu final. Un film Pixar mobilise des centaines de techniciens-artistes pendant plusieurs années. Coco (2017) a nécessité 4 ans de production et des recherches approfondies sur la culture mexicaine pour créer les 1 676 personnages uniques peuplant le Pays des Morts.</p><p class="resume-text">La capture de mouvement (motion capture) constitue une technique hybride entre prise de vue réelle et animation 3D. Des acteurs équipés de combinaisons à capteurs se déplacent dans un studio spécialisé ; leurs mouvements sont enregistrés numériquement et appliqués sur des personnages 3D. Cette technique, popularisée par Le Seigneur des Anneaux (Gollum, 2001) puis Avatar (2009), permet des performances faciales d'une expressivité inédite tout en conservant la liberté formelle de l'animation.</p><div class="highlight-box"><p>Le rendu d'un seul fotogramme de Monsters University (Pixar, 2013) nécessitait en moyenne 100 heures de calcul informatique. Le film complet comptait 110 000 fotogrammes — soit l'équivalent de 11 millions d'heures de calcul. Ces chiffres illustrent pourquoi les grands studios maintiennent des "fermes de rendu" de milliers de processeurs travaillant en parallèle.</p></div><h3>L'animation 3D dans les jeux vidéo et les effets spéciaux</h3><p class="resume-text">L'animation 3D a engendré des révolutions parallèles dans les jeux vidéo et les effets visuels de film. Les techniques développées pour le cinéma (simulation de fluides, fourrure, tissu, destruction) migrent vers les moteurs de jeux en temps réel. Unreal Engine et Unity ont démocratisé ces outils, permettant à des studios indépendants de produire des visuels auparavant réservés aux grandes productions. Des jeux comme Red Dead Redemption 2 (Rockstar, 2018) atteignent une qualité visuelle et une expressivité des personnages comparables au cinéma.</p><div class="highlight-box"><p>James Cameron a dû inventer de nouvelles technologies pour réaliser Avatar (2009) : la "caméra fusion" combinant prise de vue réelle et 3D, le "volume simulcam" permettant de voir les décors virtuels sur le plateau en temps réel. Cette innovation technique a coûté 12 ans de développement et transformé les méthodes de tournage des films à effets spéciaux massifs.</p></div>""",

    "animation/japonaise": """<h3>Hayao Miyazaki et Studio Ghibli : l'animation comme art total</h3><p class="resume-text">Hayao Miyazaki, cofondateur du Studio Ghibli en 1985 avec Isao Takahata et Toshio Suzuki, est universellement reconnu comme le plus grand réalisateur d'animation mondial. Sa filmographie — Nausicaä de la Vallée du Vent (1984), Mon voisin Totoro (1988), Princesse Mononoké (1997), Le Voyage de Chihiro (2001) — représente le sommet artistique de l'animation japonaise. Ces films partagent une philosophie cohérente : la relation entre l'homme et la nature, la critique de l'industrialisme, l'initiation des enfants à un monde complexe, la représentation de femmes protagonistes actives et autonomes.</p><p class="resume-text">La technique de Miyazaki est délibérément artisanale à l'ère du numérique. Studio Ghibli a longtemps maintenu le dessin à la main comme base de son animation, n'incorporant le numérique que pour les compositions et les effets. Cette résistance à la 3D informatique est un choix esthétique conscient : la légère irrégularité du trait à la main crée une "chaleur" organique que l'animation vectorielle parfaite ne peut reproduire. Le Voyage de Chihiro (2001), avec plus de 250 personnages différents, a nécessité 144 000 dessins animés réalisés à la main.</p><p class="resume-text">Le manga (bande dessinée japonaise) est le berceau de l'animation japonaise contemporaine. Osamu Tezuka, auteur d'Astro Boy (1952), a établi les conventions visuelles du manga moderne — grands yeux expressifs, cinématisme de la case, dramaturgie émotionnelle intense — qui fondent toujours l'esthétique anime. Cette tradition narrative graphique, populaire dans toutes les classes sociales japonaises (mangas de 50 pages dans les magazines hebdomadaires), fournit un réservoir inépuisable d'oeuvres à adapter en animation.</p><div class="highlight-box"><p>Le Voyage de Chihiro (Miyazaki, 2001) est le film le plus rentable de l'histoire japonaise au box-office national, dépassant Titanic. Son Oscar du meilleur film d'animation en 2003 fut le premier jamais décerné à un film non anglophone — consacrant l'animation japonaise comme forme artistique de premier plan au niveau mondial.</p></div><h3>L'anime et la culture pop mondiale</h3><p class="resume-text">L'anime a conquis le monde à partir des années 1990 grâce à la diffusion télévisée, puis à l'internet et aux plateformes de streaming. Dragon Ball Z, Sailor Moon, Pokémon, Neon Genesis Evangelion — ces séries ont créé une génération mondiale de fans, transformant l'anime en phénomène culturel global. Netflix, Crunchyroll et d'autres plateformes ont amplifié ce phénomène en rendant accessible simultanément dans le monde entier les nouvelles productions japonaises.</p><p class="resume-text">L'esthétique anime a influencé en retour le cinéma et l'animation occidentaux. Les Wachowski revendiquaient Ghost in the Shell (Oshii, 1995) comme source directe de Matrix (1999). Kill Bill (Tarantino, 2003) inclut une séquence animée par Production I.G. Spider-Man: New Generation (2018), primé aux Oscars, emprunte directement les techniques visuelles du manga — cases visibles, onomatopées en texte, ruptures de style dans une même scène.</p><div class="highlight-box"><p>Le marché mondial de l'anime représentait en 2022 plus de 25 milliards de dollars — dont une large part générée hors du Japon. Ce succès économique global, fondé sur des oeuvres à forte identité culturelle japonaise, est un exemple unique de "soft power" culturel non occidental dans l'industrie du divertissement mondial.</p></div>""",

    "animation/numerique": """<h3>La révolution des effets numériques dans le cinéma live</h3><p class="resume-text">L'intégration des effets numériques dans le cinéma de prises de vue réelles a transformé radicalement les possibilités narratives et visuelles depuis les années 1990. Terminator 2 (Cameron, 1991) introduit le premier personnage entièrement numérique capable d'interagir de façon convaincante avec des acteurs réels — le T-1000 en métal liquide. Jurassic Park (Spielberg, 1993) crée les premiers animaux numériques "photoréalistes" qui remplacent les marionnettes animatroniques pour les plans larges. Ces deux films établissent un nouveau paradigme : les effets visuels comme narration.</p><p class="resume-text">Industrial Light & Magic (ILM), fondé par George Lucas pour Star Wars (1977), est la société qui a le plus contribué au développement des effets visuels numériques. Ses innovations — le "morphing" numérique, la simulation de foules (dans Le Seigneur des Anneaux via Weta Digital), la capture de performance faciale — ont redéfini les limites de ce qui est filmable. Aujourd'hui, des films comme Avengers: Endgame (2019) comptent des milliers de plans à effets visuels où la frontière entre réel et numérique est indiscernable.</p><p class="resume-text">La de-aging numérique — technique permettant de rajeunir numériquement les acteurs — soulève des questions nouvelles sur l'identité et le vieillissement dans le cinéma. The Irishman (Scorsese, 2019) a utilisé cette technique pour montrer Robert De Niro, Al Pacino et Joe Pesci à différents âges. Indiana Jones 5 (2023) a représenté Harrison Ford à 40 ans avec une précision troublante. Cette technologie ouvre la voie à des performances d'acteurs décédés — soulevant des questions éthiques et juridiques non encore résolues.</p><div class="highlight-box"><p>Avatar : La Voie de l'eau (Cameron, 2022) a nécessité plus de 5 années de production pour développer les nouvelles technologies requises : simulation d'eau photoréaliste, capture de performance sous l'eau, amélioration du HFR (High Frame Rate). Le film a coûté 350 à 460 millions de dollars — et est devenu le troisième film le plus rentable de l'histoire avec plus de 2,3 milliards de dollars de recettes.</p></div><h3>La démocratisation des effets visuels</h3><p class="resume-text">Ce qui nécessitait autrefois des studios spécialisés et des budgets de plusieurs millions est devenu accessible à des cinéastes indépendants. Des logiciels comme After Effects, Nuke, DaVinci Resolve et Blender (open source) permettent à des équipes réduites de produire des effets visuels de qualité professionnelle. Des films de science-fiction indépendants comme Coherence (2013) ou Moon (2009) ont utilisé des effets numériques à petit budget d'une efficacité narrative remarquable.</p><div class="highlight-box"><p>The Mandalorian (Disney+, 2019) a révolutionné la production de films et séries grâce à son système "Volume" — un cylindre de 270 degrés d'écrans LED affichant en temps réel les décors 3D générés par le moteur de jeu Unreal Engine. Les acteurs jouent devant des décors réalistes sans fonds verts, permettant une photographie et une direction d'acteurs naturelles. Cette technologie, moins coûteuse que les tournages en extérieur, est maintenant adoptée par de nombreuses productions.</p></div>""",

    "animation/stop-motion": """<h3>Les maîtres du stop-motion : de Harryhausen à Laika</h3><p class="resume-text">Ray Harryhausen est le père fondateur du stop-motion moderne. Ses créatures mythologiques — les Harpies et le Colosse de Rhodes dans Jason et les Argonautes (1963), les Cyclopes et Méduse dans Clash of the Titans (1981) — ont défini l'esthétique du film de fantasy pendant deux décennies. Sa technique, baptisée "Dynamation", intégrait des créatures en pâte d'alumite animées image par image avec des prises de vue réelles sur des décors construits en miniature. Ce travail artisanal, réalisé par une seule personne, est une prouesse technique et artistique incomparable.</p><p class="resume-text">Nick Park et Aardman Animations ont porté la stop-motion en argile (claymation) à son sommet artistique. Wallace et Gromit, créés en 1989, sont devenus les personnages d'animation les plus aimés de Grande-Bretagne. Leur humour typiquement britannique, leurs détails visuels foisonnants (chaque arrière-plan est rempli de gags visuels), leur technique impeccable — la surface de l'argile laisse parfois les traces des doigts de l'animateur, signe d'une présence artisanale revendiquée — ont valu à Park quatre Oscars et une reconnaissance internationale.</p><p class="resume-text">Laika, studio américain fondé en 2005, a ressuscité la stop-motion à l'ère numérique en mariant les techniques traditionnelles avec des innovations technologiques. Leurs films — Coraline (2009), ParaNorman (2012), Kubo et l'armure magique (2016) — utilisent des personnages en résine imprimés en 3D pour les expressions faciales (des milliers de visages différents par personnage) combinés à des décors construits à la main et animés image par image. Cette synthèse offre une précision d'animation impossible à la main tout en conservant la texture organique caractéristique du stop-motion.</p><div class="highlight-box"><p>Pour Kubo et l'armure magique, Laika a imprimé en 3D plus de 48 000 visages différents pour animer les expressions du personnage principal. La scène de la bataille finale avec le squelette de 5 mètres est la plus grande marionnette articulée jamais utilisée dans un film stop-motion — une prouesse d'ingénierie animatronique combinée à la technique image par image traditionnelle.</p></div><h3>Le stop-motion dans la publicité, le clip et l'art contemporain</h3><p class="resume-text">Le stop-motion a connu un renouveau créatif dans les médias court-format. Les clips musicaux de Peter Gabriel — Sledgehammer (1986), Big Time (1987) — réalisés par Stephen R. Johnson avec des techniques de stop-motion variées (claymation, pixilation, objets animés) sont devenus des classiques du video-clip et ont influencé toute une génération de réalisateurs. La pixilation — stop-motion avec des acteurs réels photographiés image par image — crée des effets d'une étrangeté onirique exploitée par des artistes comme Jan Svankmajer.</p><div class="highlight-box"><p>Jan Svankmajer, cinéaste tchèque surréaliste, utilise le stop-motion comme langage poétique et subversif depuis les années 1960. Ses courts métrages — Alice (1988, adaptation de Lewis Carroll), Faust (1994) — mêlent acteurs réels, marionnettes, objets animés et cadavres d'animaux dans un univers d'une violence symbolique et d'un humour noir typiquement tchèque. Son influence sur les cinéastes de Tim Burton à les frères Quay est considérable.</p></div>""",

    "animation/traditionnelle": """<h3>L'âge d'or de Walt Disney et la naissance de l'animation industrielle</h3><p class="resume-text">Walt Disney a transformé l'animation de curiosité foraine en art industriel à part entière. Avec Blanche-Neige et les Sept Nains (1937), il réalise le premier long métrage d'animation de l'histoire hollywoodienne — un pari commercial risqué que l'industrie appelait "la folie de Disney". Le film coûta 1,5 million de dollars (fortune colossale en 1937) et rapporta 8 millions lors de sa première sortie. Son succès fonda l'empire Disney et prouva que l'animation pouvait rivaliser avec le cinéma live pour l'intensité émotionnelle et la profondeur narrative.</p><p class="resume-text">Les "Neuf Vieux" de Disney — Frank Thomas, Ollie Johnston, Eric Larson, Ward Kimball et cinq autres — ont codifié les "12 principes de l'animation" qui restent la base de l'enseignement de l'animation mondiale. Ces principes (squash and stretch, anticipation, staging, follow-through, arcs, etc.) formalisent intuitivement les lois de la physique et de la psychologie perceptuelle pour créer l'illusion de vie dans les personnages animés. Leur livre The Illusion of Life (1981) est la bible de tout animateur.</p><p class="resume-text">La période 1989-1994, dite "Renaissance Disney", voit le studio retrouver sa suprématie créative avec La Petite Sirène (1989), La Belle et la Bête (1991), Aladdin (1992) et Le Roi Lion (1994). Ces films intègrent des effets numériques (la séquence de la bibliothèque de La Belle et la Bête est la première image de synthèse dans un film Disney) tout en maintenant la tradition du dessin à la main pour les personnages. La Belle et la Bête devient le premier film d'animation nommé aux Oscars du meilleur film.</p><div class="highlight-box"><p>La séquence de la "caverne aux merveilles" dans Aladdin (1992) contenait les premiers effets "CAPS" (Computer Animation Production System) de Disney — un système numérique développé avec Pixar qui permettait la composition digitale des couches de peinture traditionnelles. Cette collaboration Disney-Pixar allait transformer l'animation mondiale dans les années suivantes.</p></div><h3>L'animation en dehors de Disney : UPA, Fleischer et les alternatives</h3><p class="resume-text">L'animation mondiale n'a jamais été le seul apanage de Disney. Les frères Fleischer (Max et Dave) créèrent Betty Boop et Popeye dans un style nettement différent — plus urbain, plus jazzy, plus irrévérencieux. Leur Superman (1941) représente l'animation la plus sophistiquée techniquement de l'époque, avec des effets atmosphériques et cinématographiques exceptionnels. La Warner Bros. produisit Bugs Bunny, Daffy Duck et les Looney Tunes sous la direction de Tex Avery — une animation subversive, méta-référentielle, violemment comique qui parodiait les conventions même du dessin animé.</p><div class="highlight-box"><p>La compagnie UPA (United Productions of America), fondée par d'anciens animateurs Disney qui avaient quitté le studio lors de la grève de 1941, développa dans les années 1950 un style radicalement différent : aplats colorés sans relief, lignes épurées, abstraction graphique. Mr. Magoo et Gerald McBoing-Boing utilisaient des techniques graphiques inspirées du modernisme pictural — une réaction consciente contre le naturalisme illusionniste de Disney.</p></div>""",

    "histoire/cinema-mondial": """<h3>Le cinéma iranien et l'esthétique de la contrainte</h3><p class="resume-text">Le cinéma iranien est l'une des cinématographies les plus respectées et les plus primées du monde depuis les années 1990, malgré (ou grâce à) les contraintes imposées par la République islamique. Abbas Kiarostami, lauréat de la Palme d'or à Cannes pour Le Goût de la cerise (1997), développe une esthétique minimaliste et philosophique — longs plans de voitures sur des routes de montagne, dialogues sur la mort et la vie — d'une profondeur méditative sans équivalent dans le cinéma mondial. Asghar Farhadi (Une Séparation, 2011; Le Client, 2016) a remporté deux Oscars du meilleur film étranger.</p><p class="resume-text">Le cinéma coréen s'est imposé sur la scène mondiale avec une rapidité spectaculaire. Park Chan-wook (Oldboy, 2003; Mademoiselle, 2016), Bong Joon-ho (Memories of Murder, 2003; The Host, 2006; Parasite, 2019) et Lee Chang-dong (Poetry, 2010) ont développé des styles distincts qui partagent une acuité sociale, un sens du genre subverti et une maîtrise formelle remarquable. Parasite de Bong Joon-ho a remporté la Palme d'or et quatre Oscars en 2020, dont le premier Oscar du meilleur film pour un film non anglophone — un séisme dans les habitudes de l'industrie.</p><p class="resume-text">Le cinéma africain reste insuffisamment distribué malgré la richesse de sa production. Sembène Ousmane (Sénégal), Souleymane Cissé (Mali), Jean-Pierre Bekolo (Cameroun) ont développé des cinémas qui interrogent l'héritage colonial, l'identité postcoloniale et les contradictions de la modernité africaine depuis les années 1960. Ces oeuvres, primées dans les grands festivals (FESPACO à Ouagadougou, Venice, Cannes), restent peu connues du grand public occidental faute de distribution adéquate.</p><div class="highlight-box"><p>Parasite (Bong Joon-ho, 2019) est le premier film non anglophone à remporter l'Oscar du meilleur film. Lors de sa victoire, Bong a remercié en coréen, puis a ajouté en anglais : "Si vous dépassez la barrière du sous-titrage, vous serez exposé à tant de films incroyables." Cette phrase résume l'enjeu de la diversité cinématographique mondiale.</p></div><h3>Bollywood et les cinémas d'Asie du Sud</h3><p class="resume-text">L'industrie cinématographique indienne (Bollywood à Mumbai, Tollywood à Hyderabad, Kollywood à Chennai) est la plus productive au monde en nombre de films : plus de 2 000 films par an en une vingtaine de langues. Les films hindi de Bollywood, avec leurs chansons et danses intégrées, leurs histoires familiales et romantiques, leurs acteurs superstars (Shah Rukh Khan, Amitabh Bachchan) rassemblent des publics de plusieurs milliards de personnes en Asie du Sud, en Afrique, au Moyen-Orient et dans la diaspora indienne mondiale.</p><div class="highlight-box"><p>RRR (S.S. Rajamouli, 2022), film d'action épique en langue telugu, est devenu le premier film indien à remporter un Oscar (pour la meilleure chanson originale "Naatu Naatu"). Ses séquences d'action et sa chorégraphie extravagante ont ébloui les spectateurs mondiaux, contribuant à l'intérêt croissant pour le cinéma indien au-delà de ses marchés traditionnels.</p></div>""",

    "histoire/contemporain": """<h3>Le cinéma de superhéros et la domination du blockbuster</h3><p class="resume-text">Le Marvel Cinematic Universe (MCU), lancé avec Iron Man (2008), a transformé l'industrie cinématographique mondiale en créant un "univers partagé" de films interconnectés sur plus de quinze ans. 32 films totalisant plus de 29 milliards de dollars de recettes mondiales — un modèle économique sans précédent fondé sur la fidélisation du public via des personnages récurrents et des arcs narratifs s'étendant sur plusieurs films. Ce modèle a influencé tous les grands studios (DC Extended Universe, Star Wars, Fast & Furious) et redéfini la notion de "franchise" cinématographique.</p><p class="resume-text">La polémique Scorsese-Marvel (2019) a cristallisé le débat sur l'état du cinéma contemporain. Martin Scorsese, réalisateur de Taxi Driver et Les Affranchis, déclarait que les films de superhéros "ne sont pas du cinéma" mais des "parcs d'attractions". Cette provocation a déclenché un débat mondial sur la place du cinéma d'auteur face au divertissement de masse, sur la standardisation du goût esthétique par les blockbusters et sur la disparition progressive des films de taille moyenne dans les salles.</p><p class="resume-text">Les plateformes de streaming — Netflix (2013), Amazon Prime Video, Disney+, HBO Max — ont profondément perturbé le modèle économique du cinéma. Elles financent des films d'auteur de qualité (Roma de Cuarón, The Irishman de Scorsese) tout en court-circuitant la sortie en salle traditionnelle. La pandémie de COVID-19 (2020-2021) a accéléré cette transition en forçant des sorties en simultané salle-streaming pour des films comme Tenet et Wonder Woman 1984, révélant l'attachement du public aux sorties en salle... et sa capacité à consommer des films chez lui.</p><div class="highlight-box"><p>La pandémie de COVID-19 a fermé les salles mondiales pendant plusieurs mois en 2020-2021, provoquant des pertes de 25 milliards de dollars pour l'industrie cinématographique mondiale. La reprise, spectaculaire avec Top Gun: Maverick (2022, 1,5 milliard de dollars) et Avatar 2 (2022, 2,3 milliards), a démontré que l'expérience de salle reste irremplaçable pour les grandes productions — mais que le marché s'est restructuré autour de films polarisant les attentes.</p></div><h3>Le numérique et la démocratisation de la réalisation</h3><p class="resume-text">La démocratisation des caméras numériques professionnelles — de la Dogme 95 de Lars von Trier aux iPhone 13 utilisés pour des longs métrages professionnels — a transformé l'accès à la réalisation. Sean Baker a tourné Tangerine (2015) avec un iPhone 5S, produisant un film sélectionné dans les plus grands festivals. Cette démocratisation des outils a permis l'émergence de cinéastes de pays et de communautés traditionnellement exclus des productions coûteuses.</p><div class="highlight-box"><p>Christopher Nolan reste l'un des rares réalisateurs contemporains à tourner exclusivement en argentique (film 65mm IMAX pour Oppenheimer, 2023), refusant délibérément le numérique. Sa position de superstar capable d'imposer ce choix coûteux à Hollywood illustre à la fois la marginalisation de la pellicule et la capacité des auteurs au statut exceptionnel à résister aux logiques économiques dominantes.</p></div>""",

    "histoire/hollywood": """<h3>L'âge d'or de Hollywood et le système des studios</h3><p class="resume-text">L'âge d'or de Hollywood (1930-1960) repose sur le "système des studios" — un mode de production industrielle dans lequel les cinq grands studios (MGM, Warner Bros., Paramount, RKO, 20th Century Fox) produisaient, distribuaient et projetaient leurs films dans leurs propres salles. Les acteurs, réalisateurs et techniciens étaient liés par des contrats d'exclusivité pluriannuels, créant une main-d'oeuvre captive et une standardisation des genres (western, comédie musicale, film noir, mélodrame) qui permettait une production de masse de 400 à 500 films annuels.</p><p class="resume-text">Le Code Hays (1934-1968), code d'autocensure de l'industrie hollywoodienne, interdisait les représentations de sexualité explicite, d'homosexualité, de nudité, de violence excessive et de dénigrement des institutions américaines. Ce code, imposé pour éviter une censure fédérale, a contraint les cinéastes à développer un langage d'allusion et de sous-entendu d'une grande sophistication. Les films noirs de Howard Hawks, John Huston ou Billy Wilder contournent le Code par des dialogues à double sens, des ellipses narratives et une mise en scène symbolique d'une habileté remarquable.</p><p class="resume-text">Le Nouvel Hollywood (1967-1980) émerge de la crise des studios, provoquée par la concurrence de la télévision et l'arrêt du système des salles exclusives (antitrust). Des cinéastes comme Francis Ford Coppola, Martin Scorsese, Steven Spielberg, Brian De Palma et George Lucas imposèrent un cinéma d'auteur américain influencé par la Nouvelle Vague française — non conventionnel, politiquement audacieux, formellement innovant. Le Parrain (1972), Chinatown (1974), Taxi Driver (1976), Star Wars (1977) et Apocalypse Now (1979) forment le corpus fondateur de cette période.</p><div class="highlight-box"><p>Le succès de Jaws (Spielberg, 1975) et de Star Wars (Lucas, 1977) a inventé le concept moderne de "blockbuster" — films à sortie large simultanée dans des milliers de salles, avec campagnes publicitaires massives. Ce modèle a remplacé le système de sortie progressive (un film s'installe d'abord à New York et Los Angeles, puis se diffuse dans le reste du pays) et transformé durablement les stratégies commerciales de Hollywood.</p></div><h3>Hollywood et la diversité : évolutions récentes</h3><p class="resume-text">L'industrie hollywoodienne fait face depuis la fin des années 2010 à des pressions croissantes pour plus de diversité — en matière de représentation à l'écran et de diversité des équipes de tournage. Black Panther (2018), premier film de superhéros à protagoniste noir avec une équipe artistique majoritairement africaine-américaine, a rapporté 1,3 milliard de dollars et remporté trois Oscars — démontrant que la diversité est aussi économiquement viable qu'artistiquement nécessaire. Le mouvement #OscarsSoWhite (2015) et #MeToo (2017) ont accéléré des changements structurels dans les organisations professionnelles et les pratiques de l'industrie.</p><div class="highlight-box"><p>L'académie des Oscars a modifié en 2020 ses critères d'éligibilité pour le meilleur film en introduisant des quotas de diversité (dans les personnages à l'écran, les équipes techniques, la formation professionnelle et le marketing). Ces nouvelles règles, applicables à partir de la 96e cérémonie en 2024, représentent un changement sans précédent dans les standards de l'industrie cinématographique.</p></div>""",

    "histoire/naissance": """<h3>Les premières décennies : du nickelodéon au cinéma parlant</h3><p class="resume-text">Les premières salles de cinéma — les "nickelodéons" américains (5 cents l'entrée) et les "cinématographes" européens — transformèrent rapidement la curiosité foraine en industrie. Dès 1905, des milliers de salles existaient aux États-Unis, projetant des films de 5 à 15 minutes devant des spectateurs debout. La production se standardisa : les "nickelodéons" demandaient des films nouveaux chaque semaine, créant une pression sur les producteurs qui inaugurait le modèle industriel du studio.</p><p class="resume-text">D.W. Griffith est le premier grand "auteur" du cinéma muet. Ses innovations techniques et narratives — le gros plan expressif, le champ-contrechamp, le montage parallèle, la profondeur de champ — ont constitué la "grammaire" du cinéma narratif que toutes les productions suivantes ont adoptée. Naissance d'une Nation (1915) est un film-charnière : techniquement révolutionnaire (3 heures, épopée historique), idéologiquement infamant (glorification du Ku Klux Klan). Intolerance (1916), réponse de Griffith aux critiques, entrelace quatre récits de l'intolérance humaine à travers les âges dans un montage d'une complexité sans précédent.</p><p class="resume-text">Le passage au cinéma parlant (1927) avec The Jazz Singer d'Alan Crosland a provoqué la plus grande révolution technologique de l'histoire du cinéma. De nombreux acteurs et réalisateurs du muet — dont la carrière reposait sur des qualités visuelles pures — ne survécurent pas à cette transition. Charlie Chaplin résista plusieurs années au parlant, convaincu que le son détruirait l'universalité du cinéma muet (Chaplin était compris dans le monde entier sans sous-titres). Ses Temps modernes (1936) est son dernier film quasi-muet — mélange de pantomime et de sons absurdes qui illustre sa résistance poétique au parlant.</p><div class="highlight-box"><p>Le premier Oscars (première cérémonie de l'Academy Awards, 1929) distingua Ailes (Wings, 1927) comme meilleur film — un muet. Sunrise (Murnau, 1927), chef-d'oeuvre expressionniste et premier film sonore expérimental, reçut le prix "unique" du film "artistique" qui ne sera jamais recréé. L'ère parlante commençait ; Hollywood allait en dix ans devenir la plus grande industrie culturelle du monde.</p></div><h3>Eisenstein et le montage comme langage</h3><p class="resume-text">Sergueï Eisenstein, théoricien et réalisateur soviétique, a développé la théorie du montage comme "collision" des images. Pour lui, deux images juxtaposées ne s'additionnent pas mais engendrent une troisième signification — comme deux notes de musique créent un accord. Le Cuirassé Potemkine (1925), avec sa célèbre séquence de l'escalier d'Odessa (12 minutes, 170 plans), est le manifeste de cette théorie : le massacre des civils par les soldats tsaristes est filmé en plans très courts, avec des ellipses temporelles délibérées, créant une tension et une émotion que le temps réel n'aurait pas produites.</p><div class="highlight-box"><p>La séquence de l'escalier d'Odessa dans Le Cuirassé Potemkine a été parodiée, citée et réinterprétée plus que tout autre séquence de l'histoire du cinéma : Brian De Palma dans Les Incorruptibles (1987), les frères Coen dans Arizona Junior (1987), Terry Gilliam dans Brazil (1985). Elle est l'archétype de ce que Roland Barthes appelait la "citation culturelle" — une image devenue signe dans le langage cinématographique mondial.</p></div>""",

    "histoire/nouvelle-vague": """<h3>Cahiers du Cinéma et la politique des auteurs</h3><p class="resume-text">La Nouvelle Vague française naît d'une théorie critique avant de devenir un mouvement cinématographique. Les Cahiers du Cinéma, fondés en 1951 par André Bazin, publient dès le milieu des années 1950 les articles d'un groupe de jeunes critiques — François Truffaut, Jean-Luc Godard, Claude Chabrol, Jacques Rivette, Éric Rohmer — qui développent la "politique des auteurs" : l'idée que le vrai créateur d'un film est son réalisateur (non le scénariste ou le producteur), et que la mise en scène est un langage personnel aussi singulier que le style littéraire.</p><p class="resume-text">Cette théorie, révolutionnaire dans un contexte de cinéma industriel où le réalisateur était souvent un "metteur en images" d'un scénario établi, conduit ses défenseurs à valoriser des cinéastes américains (Hitchcock, Hawks, Ford, Minnelli) que la critique d'art officielle ignorait comme de simples techniciens de Hollywood. En révélant la cohérence thématique et stylistique de l'oeuvre de ces réalisateurs à travers des genres différents, les Cahiers inventèrent la cinéphilie moderne et posèrent les bases d'une histoire du cinéma centrée sur les auteurs.</p><p class="resume-text">Quand Truffaut, Godard et leurs amis passèrent à la réalisation (Les Quatre Cents Coups, 1959 ; À bout de souffle, 1960), ils appliquèrent leurs théories dans des films qui révolutionnèrent le cinéma mondial : tournage en décors naturels, acteurs non professionnels, improvisation, caméra à l'épaule, montage discontinu, rupture du quatrième mur. Ce style, né de contraintes budgétaires autant que d'intentions esthétiques, fut immédiatement adopté par des cinéastes du monde entier — du Brésil (Cinema Novo) à l'Allemagne (Fassbinder) en passant par la Tchécoslovaquie (Miloš Forman).</p><div class="highlight-box"><p>À bout de souffle (Godard, 1960) utilise des raccords "faux" délibérés — les jump cuts — qui violent les règles classiques du montage continu. Cette transgression formelle, née d'une décision de réduire un film trop long par des coupes dans les plans (plutôt qu'entre les plans), devient la signature stylistique de la Nouvelle Vague et de toute une tradition de cinéma moderne qui revendique la visibilité de la construction cinématographique.</p></div><h3>La Nouvelle Vague dans le monde</h3><p class="resume-text">L'influence de la Nouvelle Vague française a été mondiale et immédiate. Au Brésil, le Cinema Novo (Glauber Rocha, Nelson Pereira dos Santos) applique ses techniques de tournage léger aux réalités sociales brésiliennes. En Italie, les cinéastes du "cinéma de qualité" (Pasolini, Bertolucci) assimilent la liberté formelle de la Nouvelle Vague dans un contexte politique marxiste. En Allemagne, le Nouveau Cinéma allemand (Fassbinder, Wenders, Herzog) développe dans les années 1970 un cinéma d'auteur austère et ambitieux. Au Japon, la Nouvelle Vague japonaise (Oshima, Yoshida, Shinoda) rompt avec les conventions du cinéma de studio traditionnel.</p><div class="highlight-box"><p>Jean-Luc Godard, décédé en 2022, est resté jusqu'à ses derniers films (Adieu au langage, 2014; Le Livre d'image, 2018) le cinéaste le plus radicalement expérimental du cinéma mondial. Sa filmographie de plus de 100 films est un laboratoire permanent des possibilités du langage cinématographique — et son influence sur les cinéastes contemporains (Xavier Dolan, Wes Anderson, Quentin Tarantino) reste considérable.</p></div>""",

    "montage/effets-visuels": """<h3>Les effets pratiques versus les effets numériques</h3><p class="resume-text">Le débat entre effets pratiques (réalisés sur le plateau avec des décors, des maquettes, des maquillages prothétiques) et effets numériques (images de synthèse ajoutées en post-production) est l'un des plus animés de l'industrie cinématographique contemporaine. Les partisans des effets pratiques — dont Christopher Nolan, J.J. Abrams et George Miller — soutiennent que la présence physique réelle d'un objet ou d'une créature donne aux acteurs quelque chose de concret à jouer, et que la lumière qui se reflète naturellement sur ces éléments crée une cohérence visuelle que les effets numériques peuvent difficilement reproduire.</p><p class="resume-text">Mad Max: Fury Road (Miller, 2015) constitue le manifeste du retour aux effets pratiques : 150 véhicules réels modifiés, des cascadeurs qui effectuèrent réellement les acrobaties spectaculaires filmées à grande vitesse, des décors construits dans le désert namibien. Le résultat, d'une puissance et d'une lisibilité rarement atteintes dans les blockbusters contemporains, contraste avec les films d'action saturés d'effets numériques dont la fluidité irréelle fragilise l'engagement du spectateur.</p><p class="resume-text">La création de créatures en effets pratiques — maquillages prothétiques, marionnettes animatroniques, combinaisons — a atteint son apogée dans les années 1980-1990 avec des artistes comme Rick Baker (An American Werewolf in London, 1981), Rob Bottin (The Thing, 1982) et Stan Winston (Aliens, 1986; Terminator 2, 1991). Ces artisans du maquillage et de l'animatronique ont développé des techniques qui restent inégalées pour la texture organique et la présence physique des créatures.</p><div class="highlight-box"><p>The Thing (John Carpenter, 1982) est considéré comme le chef-d'oeuvre des effets pratiques de créatures. Rob Bottin, qui créa les prothèses et les effets mécaniques du monstre polymorphe, travailla si intensément (sans dormir pendant de longues périodes) qu'il fut hospitalisé pour épuisement nerveux à la fin du tournage. Son travail reste une référence technique 40 ans plus tard.</p></div><h3>Les superviseurs d'effets visuels et leur rôle créatif</h3><p class="resume-text">Le superviseur d'effets visuels (VFX supervisor) est devenu l'un des rôles créatifs les plus importants dans la production de films contemporains. Il travaille dès la préparation avec le réalisateur pour déterminer comment réaliser chaque plan — effets pratiques, effets numériques, ou combinaison des deux — et supervise l'ensemble du travail des studios VFX en post-production. Des figures comme Dennis Muren (ILM), John Dykstra (Trumbull) ou Joe Letteri (Weta Digital) ont façonné l'esthétique du cinéma de science-fiction et de fantaisie des quarante dernières années.</p><div class="highlight-box"><p>Gravity (Alfonso Cuarón, 2013) a remporté l'Oscar des effets visuels pour un travail qui redéfinit ce que le numérique peut accomplir : 80% du film est entièrement numérique, y compris Sandra Bullock dans ses combinaisons spatiales, mais le réalisme de l'apesanteur et de la lumière solaire est si parfait que le film est souvent cité comme la référence absolue de la simulation de l'espace.</p></div>""",

    "montage/etalonnage": """<h3>L'étalonnage numérique et la "grading"</h3><p class="resume-text">L'étalonnage numérique (digital color grading) a révolutionné la post-production depuis les années 1990. Avant le numérique, la correction colorimétrique en laboratoire photographique permettait des ajustements limités — modifications d'expositions, filtrages globaux. Les logiciels modernes (DaVinci Resolve, Baselight) permettent un contrôle pixel par pixel de la couleur, de la luminosité et du contraste, avec des outils de sélection par forme (masques), par couleur (HSL) et par luminance qui permettent de traiter séparément les différentes zones d'une image.</p><p class="resume-text">Le "look" colorimétrique est devenu l'une des signatures stylistiques les plus reconnaissables des cinéastes contemporains. Le teal-and-orange (sarcelle et orange) omniprésent dans le cinéma d'action des années 2000-2010 — opposition entre les carnations orangées des acteurs et les ombres froides bleutées — constitue une convention quasi-universelle exploitée par Transformers, The Dark Knight et des centaines d'autres productions. Cette homogénéisation du "look" hollywoodien a paradoxalement poussé les cinéastes d'auteur à développer des palettes plus originales.</p><p class="resume-text">Luca Guadagnino, Terrence Malick et Wes Anderson ont des identités colorimétriques immédiatement reconnaissables. Anderson utilise des palettes pastel symétriques héritées du technicolor des années 1950-1960. Malick privilégie les "magic hours" — les minutes qui précèdent le coucher du soleil où la lumière naturelle est d'un or irréel. Ces choix chromatiques sont travaillés dès la prise de vue (choix des pellicules ou des capteurs, filtres) et affinés en post-production avec l'étalonneur.</p><div class="highlight-box"><p>Roger Deakins, chef-opérateur de référence travaillant avec les Coen Brothers, Denis Villeneuve et Sam Mendes, a remporté son premier Oscar pour Blade Runner 2049 (2017) après 14 nominations. Son approche — maximiser la qualité à la prise de vue pour minimiser les corrections numériques — représente une philosophie du "straight photography" de plus en plus minoritaire dans une industrie où l'étalonnage numérique peut "réparer" des lacunes de tournage.</p></div><h3>LUT, HDR et les nouvelles normes de couleur</h3><p class="resume-text">Les LUT (Look-Up Tables) sont des fichiers mathématiques qui transforment les valeurs de couleur d'un espace colorimétrique source vers un espace cible. Ils permettent de simuler sur moniteur l'aspect final du film pendant le tournage (LUT de visualisation) ou d'appliquer un "look" esthétique en post-production. L'avènement du HDR (High Dynamic Range) pour la diffusion en streaming a créé de nouveaux défis : un film masterisé en SDR (Standard Dynamic Range) pour la salle doit être re-étalonné pour le HDR télévisuel, où les blancs peuvent être deux fois plus lumineux et les noirs deux fois plus profonds.</p><div class="highlight-box"><p>Netflix impose depuis 2016 que toutes ses productions originales soient remises en 4K UHD avec un master HDR10. Cette exigence a transformé les pratiques de post-production mondiales et crée un enjeu artistique nouveau : un film peut sembler différent selon qu'il est vu en salle, sur un téléviseur HDR ou sur un téléphone OLED. L'intention créative de l'étalonneur doit maintenant anticiper ces multiples contextes de diffusion.</p></div>""",

    "montage/narratif": """<h3>Eisenstein contre Bazin : deux conceptions du montage</h3><p class="resume-text">La grande dispute théorique du cinéma des années 1920-1950 oppose deux conceptions antagoniques du montage. Pour Eisenstein, le montage est l'essence même du cinéma — c'est la collision des plans qui crée le sens, et non les plans eux-mêmes. Pour André Bazin, critique français et théoricien du "réalisme ontologique", le montage brise l'ambiguïté fondamentale du réel en imposant une signification unique. Il lui préfère le plan-séquence (long plan sans coupe) et la profondeur de champ, qui laissent au spectateur la liberté d'explorer l'espace de l'écran.</p><p class="resume-text">Orson Welles et William Wyler sont les maîtres du plan profond que défend Bazin. Citizen Kane (Welles, 1941) utilise systématiquement une profondeur de champ extrême — premier et arrière-plan également nets — pour créer des compositions visuelles polysémiques où plusieurs actions peuvent se dérouler simultanément. La scène de la cuisine avec Kane enfant visible par la fenêtre pendant que ses parents signent son contrat d'adoption réunit en un seul cadre trois niveaux de narration sans aucun montage.</p><p class="resume-text">Le débat Eisenstein-Bazin n'est pas résolu : les cinéastes contemporains utilisent librement les deux approches selon les besoins narratifs. Alfonso Cuarón dans Gravity (2013) alterne des plans-séquences de plusieurs minutes pour l'immersion dans l'espace et des montages rapides pour les crises d'urgence — exploitant consciemment les vertus de chaque approche. Alejandro Iñárritu dans Birdman (2014) simule un plan-séquence de 2 heures pour créer l'unité de temps d'une pièce de théâtre tout en maintenant la fluidité spatiale du cinéma.</p><div class="highlight-box"><p>Le plan-séquence d'ouverture de La Soif du mal (Welles, 1958) — une grue parcourant plus de deux minutes sans couper une rue mexicaine jusqu'à l'explosion de la voiture piégée — est considéré comme le plan-séquence le plus célèbre de l'histoire du cinéma. Sa restauration par Walter Murch (1998) selon les notes originales de Welles a révélé les intentions initiales du cinéaste que la production avait modifiées.</p></div><h3>Le montage des séries télévisées et ses innovations</h3><p class="resume-text">La série télévisée contemporaine a développé ses propres conventions de montage, distinctes du cinéma. Le rythme plus lent des séries (entre 40 et 60 minutes par épisode, sur plusieurs saisons) permet des arcs narratifs plus complexes et un montage qui joue sur la mémoire à long terme du spectateur. Des séries comme Breaking Bad, The Wire ou Mad Men utilisent des structures de montage sophistiquées — parallélismes entre épisodes, retours en arrière stratégiques, cliffhangers — qui tirent parti de la narration fragmentée propre au format télévisuel.</p><div class="highlight-box"><p>La séquence finale de Breaking Bad — 14 minutes sans dialogue où Walter White retrouve sa famille, récupère son argent et libère Jesse — constitue un exemple de montage narratif de très haute densité émotionnelle dans un format télévisuel. Cette maîtrise du montage télévisuel, développée par des showrunners comme Vince Gilligan, a contribué à faire de la série la forme narrative dominante de la première moitié du XXIe siècle.</p></div>""",

    "montage/post-son": """<h3>Le son dans le cinéma contemporain</h3><p class="resume-text">Le son au cinéma comprend plusieurs couches distinctes : les dialogues, les bruitages (foley), les effets sonores enregistrés ou synthétisés, la musique originale et les ambiances sonores. La conception sonore (sound design) d'un film est un art à part entière, distinct de la musique de film. Walter Murch, éditeur sonore de Francis Ford Coppola (Apocalypse Now, 1979) et de Minghella (Le Patient anglais, 1996), est considéré comme le pionnier du sound design moderne — il fut le premier à recevoir un Oscar double "son et montage" pour Apocalypse Now.</p><p class="resume-text">Les formats de son spatialisé — Dolby Atmos (2012), DTS:X (2012) — permettent de placer des sons spécifiques dans des positions tridimensionnelles de la salle, y compris au-dessus du spectateur. Un film en Dolby Atmos peut gérer jusqu'à 128 pistes audio indépendantes, dirigées vers des dizaines d'enceintes disposées autour et au plafond de la salle. Des films comme Gravity (2013) et Mad Max: Fury Road (2015) ont utilisé ces technologies pour créer des expériences sonores immersives sans précédent.</p><p class="resume-text">La musique de film a connu une évolution remarquable depuis les grands orchestres de Bernard Herrmann, Ennio Morricone et John Williams vers des compositions électroniques hybrides. Hans Zimmer a développé depuis les années 1990 un style caractéristique — nappes de cordes amplifiées, percussions lourdes, motifs minimalistes répétitifs — qui a profondément influencé la musique de film contemporaine. Jonny Greenwood (compositeur de Radiohead) pour Paul Thomas Anderson, Arca et Hildur Guðnadóttir pour Joker (2019) représentent une nouvelle génération qui brouille les frontières entre musique expérimentale et composition cinématographique.</p><div class="highlight-box"><p>Ennio Morricone, décédé en 2020, a composé plus de 500 partitions pour le cinéma et la télévision. Ses collaborations avec Sergio Leone (Pour une poignée de dollars, Le Bon, la Brute et le Truand) ont défini l'esthétique sonore du western spaghetti. Il reçut un Oscar d'honneur en 2007 pour l'ensemble de son oeuvre et un Oscar du meilleur score pour Les Huit Salopards (2015) à 87 ans.</p></div><h3>Le foley et les bruiteurs</h3><p class="resume-text">Le foley est l'art de recréer en studio des sons d'ambiance et d'actions qui n'ont pas été correctement captés au tournage. Les artistes foley marchent sur différentes surfaces (gravier, sable, bois, vinyle) pour créer le son des pas, manipulent des objets (vêtements, clefs, vaisselle) pour les sons de mouvements. Ces sons, enregistrés en synchronisation avec l'image, sont ensuite mixés avec les effets sonores enregistrés et les dialogues pour créer la bande-son finale.</p><div class="highlight-box"><p>Le son du sabre laser de Star Wars a été créé par Ben Burtt en combinant le bourdonnement d'un vieux projecteur de cinéma avec l'interférence d'un téléviseur sur un microphone. Cette découverte accidentelle est l'un des sons les plus reconnaissables de la culture populaire mondiale — et illustre comment le sound design crée un langage sonore aussi puissant que le langage visuel.</p></div>""",

    "montage/principes": """<h3>Le montage dans le cinéma expérimental et le clip</h3><p class="resume-text">Le cinéma expérimental a poussé le montage à ses limites en explorant des durées extrêmes — du film d'une seconde aux 24 heures d'Empire (Andy Warhol, 1964) — et des juxtapositions d'images radicalement non narratives. Les cinéastes structuralistes (Michael Snow, Stan Brakhage, Kenneth Anger) ont développé dans les années 1960-1970 une pratique du montage qui explore la perception pure : comment la durée d'un plan modifie notre rapport à l'image, comment la répétition crée un rythme hypnotique, comment les textures visuelles abstraites génèrent des états émotionnels spécifiques.</p><p class="resume-text">Le clip musical, né avec MTV en 1981, a inventé un langage de montage particulier basé sur la brièveté, l'impact visuel, la non-narrativité et la synchronisation avec le rythme musical. Les réalisateurs de clips — Chris Cunningham, Michel Gondry, Spike Jonze, David Fincher (avant sa carrière cinématographique) — ont développé des approches visuelles innovantes qui ont influencé en retour le cinéma commercial et publicitaire. Le clip de Gondry pour The Chemical Brothers (Star Guitar, 2002), montage entièrement synchronisé entre éléments du paysage ferroviaire et éléments musicaux, est considéré comme un chef-d'oeuvre du montage audiovisuel.</p><p class="resume-text">Les règles classiques du montage — raccord dans l'axe, raccord sur le regard, règle des 180 degrés — constituent le "continuity editing" ou "découpage classique" qui vise à rendre les coupes invisibles pour maintenir l'immersion du spectateur. Mais ces règles ne sont jamais absolues : elles sont enfreintes délibérément pour créer des effets de distanciation, de désorientation ou d'emphase. Quentin Tarantino, connu pour son montage non-chronologique (Pulp Fiction, 1994), utilise la rupture de continuité temporelle comme outil narratif et thématique.</p><div class="highlight-box"><p>Walter Murch a formulé la "règle du clignement" : le moment idéal pour couper est celui où le personnage cligne des yeux, car ce geste naturel est neurologiquement lié aux transitions de pensée. Cette observation, fondée sur la psychologie de la perception, illustre comment le montage fonctionne en harmonie avec les mécanismes cognitifs du spectateur — et non en opposition à eux.</p></div><h3>Le temps au cinéma : dilatation et compression</h3><p class="resume-text">Le cinéma a inventé des façons de manipuler le temps qui n'existaient pas dans les arts précédents. La dilatation temporelle (slow motion) crée une temporalité contemplative ou dramatique — la scène finale de Raging Bull (Scorsese, 1980) en slow motion est l'un des exemples les plus puissants. La compression temporelle (time-lapse) condense des heures en secondes. L'analepse (flash-back) et la prolepse (flash-forward) créent des architectures temporelles complexes qui correspondent à la façon dont fonctionne la mémoire humaine.</p><div class="highlight-box"><p>Dunkirk (Nolan, 2017) utilise une structure temporelle tripartite : une heure sur la plage représente une semaine, une heure en mer représente un jour, une heure dans les airs représente une heure. Ces trois temporalités convergent vers le même moment culminant — l'évacuation. Ce jeu sur le temps, inspiré de la musique (Nolan cite Elgar comme modèle), crée une expérience de la durée guerre unique dans le cinéma contemporain.</p></div>""",

    "realisation/cinematographie": """<h3>Les grands directeurs de la photographie et leur esthétique</h3><p class="resume-text">La direction de la photographie (DP ou DoP — Director of Photography) est l'un des arts les plus subtils du cinéma. Le chef-opérateur détermine la qualité de la lumière, le choix des objectifs, la mise en place de la caméra et le mouvement de celle-ci — autant de décisions qui constituent l'identité visuelle d'un film. Certains duos réalisateur/chef-opérateur sont parmi les plus créatifs de l'histoire du cinéma : Bergman/Nykvist, Coppola/Willis, Malick/Lubezki, Villeneuve/Deakins.</p><p class="resume-text">Roger Deakins (collaborateur de Joel et Ethan Coen, Sam Mendes, Denis Villeneuve) est unanimement considéré comme le plus grand chef-opérateur contemporain. Son style se caractérise par une utilisation maximale de la lumière naturelle, des palettes chromatiques très cohérentes, une sobriété dans le mouvement de caméra et une attention extrême aux conditions d'éclairage naturel. Pour Skyfall (2012), il a photographié la séquence finale en Écosse au crépuscule dans une fenêtre de lumière de quelques minutes quotidiennes.</p><p class="resume-text">Emmanuel Lubezki ("Chivo") a révolutionné la cinématographie contemporaine avec ses longs plans-séquences à la caméra portée et son utilisation de la lumière naturelle radicale. Pour Gravity (2013) avec Cuarón, il filma les astronautes dans une lumière solaire artificielle imitant précisément les conditions de l'espace. Pour The Revenant (2015, 3 Oscars), il imposa à l'équipe de ne travailler qu'en lumière naturelle dans l'Alberta canadien — un défi logistique extrême qui donna au film sa beauté sauvage caractéristique.</p><div class="highlight-box"><p>La caméra ARRI Alexa, lancée en 2010, a accéléré la transition de l'industrie cinématographique vers le numérique. Sa haute sensibilité à la lumière (jusqu'à ISO 3200 utilisable) permettait de filmer avec moins de lumière artificielle, rapprochant l'esthétique numérique de celle de la pellicule argentique. Aujourd'hui, plus de 90% des longs métrages sont tournés en numérique — la pellicule restant le choix de cinéastes comme Nolan et Quentin Tarantino qui en revendiquent les qualités esthétiques spécifiques.</p></div><h3>L'optique et la profondeur de champ</h3><p class="resume-text">Le choix des objectifs — et en particulier de leur ouverture focale qui détermine la profondeur de champ — est l'une des décisions les plus créatives de la cinématographie. Un grand téléobjectif (200mm) avec grande ouverture (f/1.4) crée une profondeur de champ très faible : le sujet est net, le fond totalement flou (bokeh). Un grand-angle (24mm) avec petite ouverture (f/16) donne une grande profondeur de champ : tout est net, du premier plan à l'infini. Ces choix déterminent le rapport de l'image au réel — flou sensuel ou vision documentaire totale.</p><div class="highlight-box"><p>Gregg Toland, directeur de la photographie de Citizen Kane (1941), avait développé avec Welles une profondeur de champ exceptionnelle en utilisant de petites ouvertures et une lumière très forte. Pour obtenir des ouvertures de f/11 à f/16 tout en maintenant une lumière cinématographiquement intéressante, il dut littéralement réinventer les techniques d'éclairage de l'époque — préfigurant les pratiques modernes de la photographie haute résolution.</p></div>""",

    "realisation/direction-acteurs": """<h3>Les méthodes de direction d'acteurs</h3><p class="resume-text">La direction d'acteurs est peut-être la compétence la plus difficile à théoriser dans la réalisation de films. Chaque réalisateur développe sa propre méthode, souvent empirique. Kubrick était connu pour ses prises répétées à l'infini — jusqu'à 127 prises pour une scène de Shining — usant les inhibitions de l'acteur jusqu'à obtenir une performance instinctive et vulnérable. Cassavetes improvisait entièrement avec des acteurs qu'il dirigeait vers des états émotionnels réels. Spielberg prépare minutieusement ses plans mais laisse une liberté totale aux acteurs dans l'exécution.</p><p class="resume-text">La "méthode" (Method Acting) est la technique la plus influente de l'histoire du jeu d'acteur américain. Développée à partir des enseignements de Stanislavski par Lee Strasberg à l'Actors Studio de New York, elle demande à l'acteur de s'identifier totalement à son personnage en s'appuyant sur ses propres souvenirs émotionnels. Marlon Brando, Al Pacino, Robert De Niro, Dustin Hoffman sont ses représentants les plus célèbres. Daniel Day-Lewis, considéré comme l'héritier de cette tradition, a passé plusieurs mois à apprendre le métier de bucheron pour un film, vécu en résidence dans un manoir pour un autre — une démarche qui culmine dans ses trois Oscars.</p><p class="resume-text">À l'opposé de l'immersion totale, des réalisateurs comme Alfred Hitchcock traitaient leurs acteurs comme des "éléments du décor" et programmaient leurs performances à l'avance. Hitchcock aurait déclaré que "les acteurs sont des bétails" — affirmation apocryphe mais illustrative d'une conception de la performance comme matériau formel à disposition du réalisateur. Cette tension entre l'acteur comme créateur autonome et l'acteur comme instrument de la vision du réalisateur traverse tout l'histoire de la mise en scène cinématographique.</p><div class="highlight-box"><p>Joaquin Phoenix a perdu 52 kg pour jouer Arthur Fleck dans Joker (2019). Cette transformation physique extrême, qui a transformé son rapport physique au personnage et influencé sa façon de se mouvoir, est typique de l'approche "méthode". Mais ce type de préparation soulève des questions éthiques : les exigences physiques extrêmes sont-elles nécessaires artistiquement, ou sont-elles une forme d'automutilation institutionnalisée par l'industrie cinématographique ?</p></div><h3>La direction d'acteurs non professionnels</h3><p class="resume-text">Des traditions cinématographiques entières ont construit leur esthétique sur l'utilisation d'acteurs non professionnels. Le néoréalisme italien (Rossellini, De Sica, Visconti) tournait avec des habitants des quartiers populaires filmés. La Nouvelle Vague française mêlait acteurs professionnels et passants filmés dans les rues de Paris. Le cinéma de Robert Bresson utilisait exclusivement des "modèles" (jamais des "acteurs") pour l'absence précisément de tout "jeu".</p><div class="highlight-box"><p>Au centre du cinéma de Pasolini, d'Abbas Kiarostami ou de Ken Loach, la direction de non-professionnels permet d'accéder à des états de présence et d'authenticité que le jeu professionnel peut artificiellement reconstituer. Cette recherche de "vérité" de la performance renvoie à la question fondamentale du cinéma : qu'est-ce qui est "vrai" à l'image ? La réalité photographiée, le jeu construit, ou l'émotion transmise au spectateur ?</p></div>""",

    "realisation/mise-en-scene": """<h3>Les grands styles de mise en scène</h3><p class="resume-text">La mise en scène est l'ensemble des décisions du réalisateur sur la disposition et le mouvement des éléments dans le cadre : acteurs, décors, lumière, caméra. Les théoriciens distinguent la mise en scène "transparente" (au service de la narration, qui cherche à se faire oublier) et la mise en scène "expressive" (qui s'affirme comme langage visuel autonome). John Ford et Howard Hawks représentent le premier modèle — leurs films sont d'une lisibilité parfaite, sans effets voyants ; Eisenstein, Welles et Kubrick représentent le second.</p><p class="resume-text">Kubrick est le maître de la composition symétrique. Ses cadres — quasi systématiquement symétriques, avec une fuite centrale qui aspire le regard — créent une esthétique formelle froide d'une beauté mathématique. Cette symétrie n'est pas décorative mais signifiante : elle crée un sentiment d'enfermement, de déterminisme, d'univers gouverné par des lois inexorables. Dans Shining (1980), les couloirs symétriques de l'hôtel Overlook enfoncent le regard dans une perspective sans fin ; dans 2001 (1968), la symétrie des vaisseaux spatiaux oppose la perfection géométrique du cosmos à la fragilité humaine.</p><p class="resume-text">Terrence Malick a développé depuis les années 2010 un style de mise en scène presque documentaire : caméras portées à l'épaule suivant les acteurs dans leurs mouvements, lentilles à longue focale qui fragmentent et floutent, lumière naturelle à toute heure. Les acteurs — souvent improvisent — sont filmés dans leurs moments d'hésitation, de distraction, de réverie plutôt que dans leurs répliques. Ce cinéma du fragment et de la présence pure constitue l'une des recherches les plus radicales sur la nature du jeu cinématographique.</p><div class="highlight-box"><p>Wong Kar-wai, cinéaste hongkongais (In the Mood for Love, 2000), tourne ses films sans scénario : il arrive sur le plateau avec une atmosphère, un sentiment, et laisse le film se construire dans le tournage et le montage. In the Mood for Love a été tourné pendant 15 mois — les scènes finales ont été filmées en Cambodge deux ans après le début du tournage. Cette méthode intuitive produit une mise en scène d'une intensité émotionnelle et d'une richesse texturale uniques dans le cinéma mondial.</p></div><h3>La caméra et son rapport au corps</h3><p class="resume-text">Les mouvements de caméra — panoramique horizontal, travelling avant/arrière, grue, caméra portée, Steadicam — constituent un vocabulaire expressif distinct. Le travelling avant crée une aspiration vers le sujet, le recadrage arrière un éloignement mélancolique. Le Steadicam (caméra stabilisée portée à l'opérateur), inventé par Garrett Brown en 1975 pour Rocky, permet des plans-séquences en mouvement fluide. Son utilisation dans Shining (les travellings dans les couloirs) et dans GoodFellas (le plan de l'entrée par la cuisine du Copacabana) en font un outil narratif de premier plan.</p><div class="highlight-box"><p>Le "zooming" — déplacement optique de la focale pendant le plan — produit un effet d'étrangement visuel que le travelling (déplacement physique de la caméra) ne peut reproduire : la distance au sujet reste la même mais sa taille dans le cadre change. Hitchcock a utilisé cette technique dans Sueur froide (Vertigo, 1958) pour créer l'effet du vertige — zoom arrière/travelling avant simultanés —, une technique qui porte depuis son nom : le "Dolly Zoom" ou "effet Vertigo".</p></div>""",

    "realisation/scenario": """<h3>La structure narrative et le "voyage du héros"</h3><p class="resume-text">Le modèle dominant du scénario hollywoodien est fondé sur la structure en trois actes théorisée par Syd Field dans son manuel Screenplay (1979) et enrichi par Christopher Vogler dans The Writer's Journey (1992). Ce dernier, s'inspirant des travaux de l'anthropologue Joseph Campbell sur le "monomythe", propose la structure du "voyage du héros" comme archétype narratif universel présent dans les mythes de toutes les cultures : appel à l'aventure, refus de l'appel, guide (mentor), franchissement du seuil, épreuves, révélation, retour transformé.</p><p class="resume-text">Cette structure, si elle décrit effectivement les mythes collectifs (Star Wars, Le Seigneur des Anneaux, Matrix s'y conforment parfaitement), est critiquée pour son caractère prescriptif. Robert McKee, autre "gourou" du scénario américain dont le séminaire Story a formé des générations de scénaristes, propose une approche plus nuancée basée sur le "conflit" comme moteur fondamental de tout récit. Ces théorisations, massivement adoptées par Hollywood, ont créé une standardisation des structures narratives que les cinéastes indépendants et mondiaux cherchent précisément à contourner.</p><p class="resume-text">Les scénaristes de télévision contemporaine ont développé des structures narratives alternatives, adaptées au format sériel. Les showrunners de séries comme The Wire, Breaking Bad ou Mad Men pensent en termes de saisons (arcs de 13 épisodes) et de séries complètes (arcs de 5 à 7 saisons), créant des trajectoires de personnages d'une durée et d'une complexité inédites dans l'histoire de la narration audiovisuelle. Cette "novelisation" de la télévision a attiré vers le petit écran de grands auteurs littéraires (Jonathan Franzen, Richard Price) et cinématographiques (Jane Campion, David Fincher).</p><div class="highlight-box"><p>Chinatown (Robert Towne, 1974) est le scénario original le plus étudié dans les écoles de cinéma mondiales. Son intrigue complexe, son protagoniste défaillant, sa fin tragique sans rédemption — tout contredit les prescriptions du "voyage du héros". Pourtant, le film est parfait selon tous les critères de la narration classique. La leçon : les règles du scénario décrivent des tendances statistiques, pas des lois absolues.</p></div><h3>Le scénariste et la question de l'auteur</h3><p class="resume-text">Le statut du scénariste dans le cinéma est paradoxal : il est souvent le premier créateur d'un film mais rarement son "auteur" reconnu. La "politique des auteurs" des Cahiers du Cinéma valorise le réalisateur au détriment du scénariste — une position qui reflète la réalité hollywoodienne où les scénarios sont souvent réécrits par plusieurs personnes, mais efface la contribution fondamentale des grands scénaristes.</p><div class="highlight-box"><p>Billy Wilder était à la fois réalisateur et scénariste (avec I.A.L. Diamond ou Charles Brackett) — une combinaison qui lui permettait de contrôler l'intégralité du processus créatif. Ses scénarios pour Certains l'aiment chaud (1959), Sunset Boulevard (1950) et L'Appartement (1960) sont des modèles de construction dramatique, de dialogue et de structure qui sont encore étudiés dans toutes les écoles de scénario.</p></div>""",

    "realisation/son-musique": """<h3>Les compositeurs emblématiques du cinéma</h3><p class="resume-text">La collaboration entre réalisateur et compositeur est l'une des plus créatives dans l'histoire du cinéma. Certains partenariats ont produit des oeuvres indissociables : Hitchcock et Bernard Herrmann (Psychose, Vertigo, Sueur froide) — la musique d'Herrmann ne "commente" pas l'image mais crée une deuxième couche de signification psychologique. Sergio Leone et Ennio Morricone ont inventé ensemble le son du western spaghetti — les thèmes de Morricone précédaient les images, Leone tournait en play-back sur la musique. Stanley Kubrick et Gustav Mahler, Richard Strauss, Ligeti — son utilisation de musiques classiques pré-existantes comme bande sonore révolutionne le rapport image/musique.</p><p class="resume-text">John Williams est le compositeur de films le plus connu du grand public mondial. Ses thèmes pour Star Wars, Jaws, Indiana Jones, Schindler's List et Harry Potter sont parmi les plus reconnaissables de la culture populaire. Son style néo-romantique — mélodies puissantes, orchestrations symphoniques pleines — crée une accessibilité émotionnelle immédiate qui a redéfini les attentes du public pour la musique de film depuis les années 1970. Williams a reçu 5 Oscars et 54 nominations — un record absolu dans toutes les catégories.</p><p class="resume-text">La musique diegétique (entendue par les personnages du film) et non-diegétique (bande originale entendue seulement par le spectateur) constituent deux registres distincts. Certains cinéastes travaillent avec les frontières entre ces deux types : dans Mulholland Drive (Lynch, 2001), une scène au club Silencio illustre que "tout est enregistré" — une chanteuse s'effondre mais la musique continue, révélant que le son était une illusion. Cette scène métacinématographique est l'une des plus puissantes de l'histoire du cinéma sur la nature du son filmique.</p><div class="highlight-box"><p>Hans Zimmer, compositeur de The Lion King, Gladiator, The Dark Knight et Inception, dirige une équipe de compositeurs assistants dans son studio Remote Control Productions — une "factory" qui produit des dizaines de partitions par an. Cette organisation industrielle de la composition, critiquée par les puristes, lui a permis de développer un style reconnaissable et une présence omniprésente dans le cinéma commercial mondial des trente dernières années.</p></div><h3>Le silence comme outil sonore</h3><p class="resume-text">Le silence est l'un des outils sonores les plus puissants du cinéma — et l'un des plus difficiles à utiliser. Après des décennies de soundscapes denses et de musiques omniprésentes, des réalisateurs comme Alfonso Cuarón (Children of Men, 2006), Denis Villeneuve (Arrival, 2016) et Lynne Ramsay (You Were Never Really Here, 2017) ont renoué avec des durées de silence qui créent une tension et une attention du spectateur qu'aucune musique ne pourrait produire.</p><div class="highlight-box"><p>La bataille de la ferme dans Children of Men (Cuarón, 2006) — plan-séquence de plusieurs minutes d'une violence extrême — est d'abord filmée avec la musique habituelle des scènes d'action. Puis Cuarón a décidé de supprimer toute musique, ne laissant que les bruits de guerre. Le résultat, d'une brutalité documentaire insoutenable, reste l'une des scènes d'action les plus saisissantes du cinéma récent — illustrant que l'absence de musique peut être plus dramatiquement puissante que n'importe quelle partition.</p></div>""",
}


def enrich_discipline(discipline, enrichments, base_path="C:/Users/nicol/Desktop/Projets/Divers/Curiosita/assets/content"):
    filepath = f"{base_path}/{discipline}.json"
    with open(filepath, encoding='utf-8') as fp:
        data = json.load(fp)

    changed = 0
    for key, addition in enrichments.items():
        if key not in data['pages']:
            print(f"  WARNING: key not found: {key}")
            continue
        content = data['pages'][key]['content']
        if '<section class="content-section" id="quiz">' in content:
            content = content.replace(
                '<section class="content-section" id="quiz">',
                addition + '\n<section class="content-section" id="quiz">'
            )
        else:
            content = content.rstrip()
            if content.endswith('</section>'):
                content = content[:-10] + addition + '</section>'
            else:
                content += addition
        data['pages'][key]['content'] = content
        new_len = len(data['pages'][key]['content'])
        print(f"  {key}: {new_len} chars")
        changed += 1

    with open(filepath, 'w', encoding='utf-8') as fp:
        json.dump(data, fp, ensure_ascii=False, indent=2)
    print(f"Saved {discipline}.json ({changed} articles enriched)")

print("=== cinema ===")
enrich_discipline("cinema", ENRICHMENTS)
print("\nDone!")
